"""Draft construction for NRS 484B.217(2) left-turn stripe crossing.

The Native execution/capture path remains unfinished. CARLA is never imported
at module import or by offline checks.
"""
import argparse
import json
from pathlib import Path

SCENE = Path(__file__).with_name('scene.json')


def load_scene(path=SCENE):
    scene = json.loads(Path(path).read_text())
    if (scene['law_id'], scene['cell_id'], scene['actor']) != (
            'NRS-484B-217-2', 'C109755', 'motor_vehicle_driver'):
        raise ValueError('wrong frozen identity')
    if not scene['approach_lane_center_y_m'] < scene['stripe_y_m'] < scene['opposing_lane_center_y_m']:
        raise ValueError('striping is not between opposing lanes')
    if not scene['start_x_m'] < scene['signal_start_x_m'] < scene['crossing_x_m']:
        raise ValueError('signal station must precede stripe crossing')
    if scene['exit_y_m'] <= scene['opposing_lane_center_y_m']:
        raise ValueError('left-turn exit must cross the opposing side')
    return scene


def route(scene):
    y = scene['approach_lane_center_y_m']
    x = scene['crossing_x_m']
    return [(scene['start_x_m'], y), (scene['signal_start_x_m'], y),
            (x-3.0,y), (x,scene['stripe_y_m']), (x,scene['opposing_lane_center_y_m']),
            (x,scene['exit_y_m'])]


def crosses_stripe(scene):
    points = route(scene)
    return any(a[1] < scene['stripe_y_m'] <= b[1] for a,b in zip(points,points[1:]))


def require_marking(carla_map, location, expected='Solid'):
    waypoint = carla_map.get_waypoint(location)
    if waypoint is None:
        raise ValueError('map has no approach waypoint at stripe crossing')
    marking = getattr(waypoint, 'left_lane_marking', None)
    if marking is None or expected.lower() not in str(getattr(marking,'type','')).lower():
        raise ValueError('map lacks solid no-passing striping at crossing')
    return waypoint


def choose(library, pattern):
    matches = list(library.filter(pattern))
    if not matches:
        raise ValueError('required vehicle blueprint missing: '+pattern)
    return matches[0]


def spawn_scene(world, scene, transform_factory):
    """Create three distinct vehicles; caller retains ownership for cleanup."""
    library = world.get_blueprint_library()
    specs = [('ego','ego_blueprint',scene['start_x_m'],scene['approach_lane_center_y_m'],0),
             ('oncoming','oncoming_blueprint',scene['oncoming_start_x_m'],scene['opposing_lane_center_y_m'],180),
             ('following','following_blueprint',scene['following_start_x_m'],scene['approach_lane_center_y_m'],0)]
    actors={}
    for name,key,x,y,yaw in specs:
        actors[name] = world.spawn_actor(choose(library,scene[key]),transform_factory(x,y,0,yaw))
    if len({id(a) for a in actors.values()}) != len(actors):
        raise ValueError('world reused an actor for distinct traffic roles')
    return actors


def controller_command(scene, x_m, turn_started):
    signal = bool(scene['signal_enabled'] and x_m >= scene['signal_start_x_m'])
    return {'left_signal':signal,'steer':0.4 if turn_started else 0.0,
            'throttle':0.3 if not turn_started else 0.2,'brake':0.0}


def check():
    scene=load_scene()
    assert crosses_stripe(scene)
    assert route(scene)[0][1] < scene['stripe_y_m'] < route(scene)[-1][1]
    assert controller_command(scene,scene['signal_start_x_m']-1,False)['left_signal'] is False
    print(json.dumps({'geometry_checked':True,'map_marking_requires_native_verification':True}))


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    parser.add_argument('--output-dir')
    parser.add_argument('--host',default='127.0.0.1')
    parser.add_argument('--port',type=int,default=2000)
    args=parser.parse_args()
    if args.check:check()
    else:raise SystemExit('Native execution/capture unfinished for this partial construction')


if __name__=='__main__':main()

"""Saved-only source-bound stripe crossing measurements; no legal safety threshold."""
import argparse
import hashlib
import json
from pathlib import Path


def sha(path):return hashlib.sha256(path.read_bytes()).hexdigest()


def source(attempt, acquisition, name):
    info=acquisition.get(name)
    path=attempt/name
    if not info or info.get('kind')!='original_native' or not path.is_file() or sha(path)!=info.get('sha256'):
        raise ValueError('missing or stale original Native source: '+name)
    return path


def measure(attempt):
    attempt=Path(attempt);acquisition=json.loads((attempt/'acquisition.json').read_text())
    history=source(attempt,acquisition,'turn-history.jsonl')
    zone=source(attempt,acquisition,'zone-context.json')
    rows=[json.loads(line) for line in history.read_text().splitlines() if line.strip()]
    context=json.loads(zone.read_text())
    if not rows or context.get('zone_kind')!='marked_no_passing_zone' or context.get('striping_source')!='native_map':
        raise ValueError('marked zone or original turn history missing')
    stripe=context['stripe_y_m'];first=None;previous=None
    for row in rows:
        if previous and (row['frame']<=previous['frame'] or row['time_s']<=previous['time_s']):
            raise ValueError('original frame/time order invalid')
        if previous and previous['ego_center_y_m']<stripe<=row['ego_center_y_m'] and first is None:
            first=row
        previous=row
    if first is None:raise ValueError('no observed stripe crossing')
    if not all('left_signal' in row and 'oncoming_body_gap_m' in row and 'following_body_gap_m' in row for row in rows):
        raise ValueError('signal or traffic measurements missing')
    if any(row['oncoming_body_gap_m']<0 or row['following_body_gap_m']<0 for row in rows):
        raise ValueError('invalid traffic gap measurement')
    activated=[r for r in rows if r['left_signal'] and r['time_s']<=first['time_s']]
    return {'format':'worker-stripe-measurements','crossing_frame':first['frame'],
            'crossing_time_s':first['time_s'],'signal_started_s':activated[0]['time_s'] if activated else None,
            'signal_active_at_crossing':bool(first['left_signal']),
            'minimum_oncoming_body_gap_m':min(r['oncoming_body_gap_m'] for r in rows),
            'minimum_following_body_gap_m':min(r['following_body_gap_m'] for r in rows),
            'zone_context_sha256':acquisition['zone-context.json']['sha256'],
            'turn_history_sha256':acquisition['turn-history.jsonl']['sha256'],
            'legal_safety_and_impediment':'unresolved'}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',required=True);parser.add_argument('--output',required=True)
    args=parser.parse_args();Path(args.output).write_text(json.dumps(measure(args.attempt),indent=2)+'\n')
if __name__=='__main__':main()

"""Independent signal comparison over saved, source-bound measurements."""
import argparse
import json
from pathlib import Path

FIXED=('law_id','cell_id','actor_id','map_sha256','stripe_geometry_sha256',
       'route_sha256','oncoming_policy_sha256','following_policy_sha256',
       'camera_contract_sha256','duration_s')


def audit(signaled,unsignaled):
    for name in FIXED:
        if not signaled.get(name) or not unsignaled.get(name):
            raise ValueError('missing fixed condition: '+name)
        if signaled[name]!=unsignaled[name]:
            raise ValueError('fixed condition differs: '+name)
    for label,record in (('signaled',signaled),('unsignaled',unsignaled)):
        measured=record.get('measurement')
        if not measured or measured.get('format')!='worker-stripe-measurements' or not measured.get('turn_history_sha256') or not measured.get('zone_context_sha256'):
            raise ValueError(label+': missing source-bound stripe measurement')
        if measured['crossing_time_s'] is None:
            raise ValueError(label+': stripe crossing absent')
    a=signaled['measurement'];b=unsignaled['measurement']
    if not a['signal_active_at_crossing'] or a['signal_started_s'] is None or a['signal_started_s']>=a['crossing_time_s']:
        raise ValueError('signal not observed before crossing')
    if b['signal_active_at_crossing'] or b['signal_started_s'] is not None:
        raise ValueError('unsignaled comparison has observed signal')
    return {'comparison_id':'turn_signal_before_stripe','passed':True,
            'fixed_conditions':list(FIXED),'difference':'observed signal activation before crossing'}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('signaled');parser.add_argument('unsignaled')
    args=parser.parse_args();print(json.dumps(audit(json.loads(Path(args.signaled).read_text()),
                                                  json.loads(Path(args.unsignaled).read_text())),indent=2))
if __name__=='__main__':main()

"""Independent local source/lifecycle audit for one delivered stripe case.

Run after saved processing with an actual Native attempt and pinned media decode
receipt. A passing result is software/physical-evidence validation, not law.
"""
import argparse
import hashlib
import json
from pathlib import Path


def sha(path):return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def read(path):return json.loads(Path(path).read_text())

def rows(path):return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def audit(attempt, processing, decode_receipt, media_verify=None):
    attempt=Path(attempt);processing=Path(processing)
    seal=read(attempt/'capture-seal.json')
    if seal.get('events')!=['capture_finished','encoders_closed','restoration_verified']:
        raise ValueError('Native capture lifecycle incomplete')
    for name,checksum in seal.get('sources',{}).items():
        if not (attempt/name).is_file() or sha(attempt/name)!=checksum:
            raise ValueError('sealed original missing or changed: '+name)
    exit_record=read(attempt/'native-exit.json')
    if exit_record.get('event')!='native_exit' or exit_record.get('capture_seal_sha256')!=sha(attempt/'capture-seal.json'):
        raise ValueError('Native exit does not bind sealed capture')
    owner=read(attempt/'owner-release.json')
    if owner.get('event')!='owner_released' or owner.get('operator_attested') is not True or owner.get('native_exit_sha256')!=sha(attempt/'native-exit.json'):
        raise ValueError('owner release missing or stale')
    result=read(attempt/'result.json')
    if not all(result.get(key) is True for key in ('setup_confirmed','behavior_attempted','maneuver_completed')):
        raise ValueError('physical completion not confirmed')
    trace=rows(attempt/'trace.jsonl');mapping=rows(attempt/'video_frames.jsonl')
    if not trace or len(trace)!=len(mapping) or any(
        t['frame']!=m['carla_frame'] or abs(t['time_s']-m['time_s'])>1e-6 or m['video_frame']!=i
        for i,(t,m) in enumerate(zip(trace,mapping))):
        raise ValueError('original frame/time join missing or changed')
    processed=read(processing)
    if processed.get('format')!='worker-saved-processing' or processed.get('passed') is not True or processed.get('recorded_only') is not True:
        raise ValueError('saved processing receipt absent or failed')
    saved_result=Path(processed.get('result',''))
    if not saved_result.is_file() or processed.get('result_sha256')!=sha(saved_result):
        raise ValueError('saved result hash differs')
    if media_verify is None:
        from worker_exchange.media import verify_receipt
        media_verify=verify_receipt
    video=Path(processed.get('analysis_directory',''))/'raw.mkv'
    if not video.is_file():
        raise ValueError('saved primary video missing')
    media_verify(video,decode_receipt,len(mapping),mapping_sha256=sha(attempt/'video_frames.jsonl'))
    return {'format':'worker-delivery-audit','passed':True,'case_id':result.get('case_id'),
            'native_result_sha256':sha(attempt/'result.json'),'frame_count':len(mapping),
            'trace_sha256':sha(attempt/'trace.jsonl'),'frame_map_sha256':sha(attempt/'video_frames.jsonl'),
            'video_sha256':sha(video),'source_decode_receipt_sha256':sha(decode_receipt),
            'legal_verdict':None}


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--attempt',required=True)
    parser.add_argument('--processing',required=True);parser.add_argument('--decode-receipt',required=True)
    args=parser.parse_args();print(json.dumps(audit(args.attempt,args.processing,args.decode_receipt),indent=2))
if __name__=='__main__':main()
